const crypto = require('crypto');

const EVENTS = ['item:added', 'item:updated', 'item:completed', 'item:deleted'];
const ignored = (why) => [{ json: { status: 200, reply: `ignored: ${why}` } }];

// Todoist signs the raw request body, so verify before parsing anything.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const given = Buffer.from($input.first().json.headers['x-todoist-hmac-sha256'] ?? '');
const secret = $env.TODOIST_CLIENT_SECRET;
if (!secret) throw new Error('TODOIST_CLIENT_SECRET is not set');
const expected = Buffer.from(crypto.createHmac('sha256', secret).update(raw).digest('base64'));
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  return [{ json: { status: 401, reply: 'bad signature' } }];
}

const { event_name, event_data: item, event_data_extra: extra } = JSON.parse(raw.toString('utf8'));
if (!EVENTS.includes(event_name)) return ignored(event_name);

// Todoist API priority is inverted: 4 = p1, 1 = p4
const prio = (p) => `p${5 - (p ?? 1)}`;
const due = (d) => d?.string || d?.date || 'none';
const labels = (l) => (l?.length ? l.join(', ') : 'none');
const clip = (s, n = 300) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
// Older webhook payloads carry numeric ids plus v2_* ids; the API wants the latter.
const projectId = (i) => i?.v2_project_id ?? i?.project_id;

const changes = [];
if (event_name === 'item:updated') {
  // Completing, uncompleting, and every occurrence of a recurring task also
  // send item:updated; those have their own events.
  const intent = extra?.update_intent;
  if (intent && intent !== 'item_updated') return ignored(`update_intent ${intent}`);

  const old = extra?.old_item;
  if (old) {
    const diff = (name, a, b) => { if (a !== b) changes.push({ name, value: clip(`${a} → ${b}`), inline: false }); };
    diff('Content', old.content, item.content);
    diff('Due', due(old.due), due(item.due));
    diff('Priority', prio(old.priority), prio(item.priority));
    diff('Labels', labels(old.labels), labels(item.labels));
    if ((old.description ?? '') !== (item.description ?? '')) changes.push({ name: 'Description', value: 'changed', inline: false });
    if (projectId(old) !== projectId(item)) changes.push({ name: 'Moved', value: 'from another project', inline: false });
    // Reordering, collapsing, and similar edits are not worth a message.
    if (!changes.length) return ignored('no visible change');
  }
}

return [{ json: { status: 200, event_name, item, changes, project_id: projectId(item) ?? '' } }];

const STYLE = {
  'item:added': { title: 'Task added', color: 0x3b82f6 },
  'item:updated': { title: 'Task updated', color: 0xf59e0b },
  'item:completed': { title: 'Task completed', color: 0x22c55e },
  'item:deleted': { title: 'Task deleted', color: 0xef4444 },
};

const { event_name, item, changes, project_id } = $('Verify and parse').first().json;
const style = STYLE[event_name];

// Walk from the task's project up through its parents. Empty when the lookup
// failed or no API token is configured.
const byId = new Map(($input.first().json.results ?? []).map((p) => [p.id, p]));
const chain = [];
for (let p = byId.get(project_id); p && chain.length < 10; p = byId.get(p.parent_id)) chain.push(p);
const project = chain.map((p) => p.name).reverse().join(' / ');

// {"Project name": "https://discord.com/api/webhooks/..."}; the nearest mapped
// project wins, so sub-projects inherit. Everything else goes to the default.
let channels = {};
try {
  const parsed = JSON.parse($env.DISCORD_PROJECT_WEBHOOKS || '{}');
  for (const [name, url] of Object.entries(parsed)) channels[name.trim().toLowerCase()] = url;
} catch (e) {
  channels = {};
}
const mapped = chain.find((p) => channels[p.name.trim().toLowerCase()]);
const webhook_url = mapped ? channels[mapped.name.trim().toLowerCase()] : $env.DISCORD_WEBHOOK_URL;

const fields = [];
if (project) fields.push({ name: 'Project', value: project, inline: true });
if (event_name === 'item:updated' && changes.length) {
  fields.push(...changes);
} else {
  if (item.due?.string) fields.push({ name: 'Due', value: item.due.string, inline: true });
  // Todoist API priority is inverted: 4 = p1, 1 = p4
  if (item.priority > 1) fields.push({ name: 'Priority', value: `p${5 - item.priority}`, inline: true });
}

const embed = {
  title: style.title,
  description: (item.content ?? '').slice(0, 2000),
  color: style.color,
  fields,
  timestamp: new Date().toISOString(),
};
// A deleted task has nothing to link to.
if (event_name !== 'item:deleted') embed.url = `https://app.todoist.com/app/task/${item.v2_id ?? item.id}`;

return [{ json: { webhook_url, discord: { embeds: [embed] } } }];
